// This script is generated by Gemini
using UnityEngine;
using UnityEngine.InputSystem;
using UnityEngine.SceneManagement;
using System.Collections; 

public class GameMenu : MonoBehaviour
{
    public static GameMenu Instance { get; private set; }
    public static bool IsPlaying { get; private set; }
    static bool skipMainMenu = false;

    [Header("UI Panels")]
    [SerializeField] GameObject mainMenuPanel;
    [SerializeField] GameObject pauseMenuPanel;
    [SerializeField] GameObject gameOverPanel;
    [SerializeField] GameObject pauseBlur;

    [Header("Audio")]
    [SerializeField] AudioSource gameOverAudio;
    [Tooltip("Drag the AudioSource containing the button click sound here")]
    [SerializeField] AudioSource uiClickAudio;
    [Tooltip("Drag the AudioSource containing the button hover sound here")]
    [SerializeField] AudioSource uiHoverAudio;

    enum State { MainMenu, Playing, Paused, GameOver }
    State state;

    void Awake()
    {
        Instance = this;
    }

    void Start()
    {
        if (gameOverAudio != null) gameOverAudio.ignoreListenerPause = true;
        if (uiClickAudio != null) uiClickAudio.ignoreListenerPause = true;
        
        // CRITICAL: Hover sounds must play even when the game is paused
        if (uiHoverAudio != null) uiHoverAudio.ignoreListenerPause = true;

        if (skipMainMenu)
        {
            skipMainMenu = false;
            SetState(State.Playing);
        }
        else
        {
            SetState(State.MainMenu);
        }
    }

    void Update()
    {
        if (Keyboard.current == null || !Keyboard.current.escapeKey.wasPressedThisFrame)
            return;

        if (state == State.Playing) SetState(State.Paused);
        else if (state == State.Paused) SetState(State.Playing);
    }

    public static event System.Action OnGameOver;

    public void GameOver()
    {
        if (state != State.Playing) return;

        if (gameOverAudio != null) gameOverAudio.Play();

        OnGameOver?.Invoke();
        SetState(State.GameOver);
    }

    // ----- UI Button Actions -----

    public void PlayHoverSound()
    {
        if (uiHoverAudio != null) uiHoverAudio.Play();
    }

    private void PlayClickSound()
    {
        if (uiClickAudio != null) uiClickAudio.Play();
    }

    public void Play()   
    {
        PlayClickSound();
        SetState(State.Playing);
    }

    public void Resume() 
    {
        PlayClickSound();
        SetState(State.Playing);
    }

    public void PlayAgain()
    {
        PlayClickSound();
        skipMainMenu = true;
        StartCoroutine(DelayedReload());
    }

    public void MainMenu()
    {
        PlayClickSound();
        skipMainMenu = false;
        StartCoroutine(DelayedReload());
    }

    public void Quit()
    {
        PlayClickSound();
        StartCoroutine(DelayedQuit());
    }

    // ----- Coroutines for smooth sound transitions -----

    private IEnumerator DelayedReload()
    {
        yield return new WaitForSecondsRealtime(0.2f); 
        ReloadScene();
    }

    private IEnumerator DelayedQuit()
    {
        yield return new WaitForSecondsRealtime(0.2f);
#if UNITY_EDITOR
        UnityEditor.EditorApplication.isPlaying = false;
#else
        Application.Quit();
#endif
    }

    // ----- Helpers -----

    void ReloadScene()
    {
        Time.timeScale = 1f;
        AudioListener.pause = false; 
        SceneManager.LoadScene(SceneManager.GetActiveScene().buildIndex);
    }

    void SetState(State newState)
    {
        state = newState;
        IsPlaying = state == State.Playing;

        mainMenuPanel.SetActive(state == State.MainMenu);
        pauseMenuPanel.SetActive(state == State.Paused);
        gameOverPanel.SetActive(state == State.GameOver);

        if (pauseBlur != null)
            pauseBlur.SetActive(state == State.Paused || state == State.GameOver);

        Time.timeScale = IsPlaying ? 1f : 0f;
        AudioListener.pause = !IsPlaying;
    }
}